import java.util.*;

class Solution {
  public long findKthSmallest(int[] coins, int k) {
    long low = 1, high = (long) Arrays.stream(coins).min().getAsInt() * k;
    while (low < high) {
      long middle = low + (high - low) / 2;
      if (countAtMost(middle, coins) >= k) high = middle;
      else low = middle + 1;
    }
    return low;
  }

  private long countAtMost(long value, int[] coins) {
    long count = 0;
    int n = coins.length;
    for (int mask = 1; mask < (1 << n); mask++) {
      long multiple = 1;
      boolean overflow = false;
      for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) != 0) {
          long gcd = gcd(multiple, coins[i]);
          long factor = coins[i] / gcd;
          if (multiple > value / factor) {
            overflow = true;
            break;
          }
          multiple *= factor;
        }
      }
      if (!overflow) {
        long terms = value / multiple;
        count += Integer.bitCount(mask) % 2 == 1 ? terms : -terms;
      }
    }
    return count;
  }

  private long gcd(long a, long b) {
    while (b != 0) {
      long remainder = a % b;
      a = b;
      b = remainder;
    }
    return a;
  }
}
